---
name: OpenCode
run-name: "OpenCode #${{ github.event.issue.number || inputs.issue_number }}"
on:
  issues:
    types:
      - opened
  workflow_dispatch:
    inputs:
      issue_number:
        required: true
        type: string
        description: Existing issue to run
permissions: {}
concurrency:
  group: opencode-issue-${{ github.repository }}-${{ github.event.issue.number || inputs.issue_number }}
  cancel-in-progress: false
jobs:
  prepare:
    runs-on: ubuntu-latest
    permissions:
      id-token: write
      contents: write
      issues: write
      actions: write
    outputs:
      approved: ${{ steps.prepare.outputs.approved }}
      issue_number: ${{ steps.prepare.outputs.issue_number }}
      request: ${{ steps.prepare.outputs.request }}
      issue_title: ${{ steps.prepare.outputs.issue_title }}
      labels_json: ${{ steps.prepare.outputs.labels_json }}
      sender: ${{ steps.prepare.outputs.sender }}
      target_ref: ${{ steps.prepare.outputs.target_ref }}
      target_sha: ${{ steps.prepare.outputs.target_sha }}
    steps:
      - name: Authenticate status callbacks
        continue-on-error: true
        shell: bash
        env:
          ISSUE_NUMBER: ${{ github.event.issue.number || github.event.needs.prepare.outputs.issue_number }}
          OMGITHUB_ORIGIN: ${{ vars.OMGITHUB_ORIGIN || 'https://omgithub.com' }}
        run: |
          /usr/bin/time -p node --input-type=module <<'NODE'
          import { appendFileSync } from 'node:fs';
          const env = process.env;
          const origin = env.OMGITHUB_ORIGIN.replace(/\/$/, '');
          const url = new URL(env.ACTIONS_ID_TOKEN_REQUEST_URL);
          url.searchParams.set('audience', origin);
          async function json(url, options) {
            const response = await fetch(url, { ...options, signal: AbortSignal.timeout(15000) });
            if (!response.ok) throw new Error(`Callback authentication HTTP ${response.status}`);
            return response.json();
          }
          for (let attempt = 0; attempt < 8; attempt++) {
            try {
              const identity = await json(url, { headers: { authorization: `Bearer ${env.ACTIONS_ID_TOKEN_REQUEST_TOKEN}` } });
              const { token } = await json(`${origin}/api/github/${env.GITHUB_REPOSITORY}/issues/${env.ISSUE_NUMBER}/callback-token`, {
                method: 'POST', headers: { authorization: `Bearer ${identity.value}`, 'content-type': 'application/json' },
                body: JSON.stringify({ run: env.GITHUB_RUN_ID, attempt: Number(env.GITHUB_RUN_ATTEMPT) })
              });
              console.log(`::add-mask::${token}`);

const { createHash } = require('node:crypto')
const { mkdirSync, readFileSync, writeFileSync, existsSync, renameSync, appendFileSync } = require('node:fs')
const { join } = require('node:path')

function webDirectory(env) { return env.OMGITHUB_CAPTURE_WEB_DIR || env.OPENCODE_WEB_DIR }
// Controller-owned loopback ports never count as project pages: the OpenCode
// server default, and cloudflared's default metrics range. Runtime-allocated
// controller ports come from the workflow env and $OPENCODE_WEB_DIR/controller-ports.
const CONTROLLER_PORTS = [4096, 20241, 20242, 20243, 20244, 20245]
const CONTROLLER_PORT_ENV = ['OPENCODE_WEB_PORT', 'OPENCODE_CONTROL_PORT', 'PROJECT_FILE_PORT']
const LOOPBACK_HOSTS = new Set(['localhost', '127.0.0.1', '[::1]'])
function controllerPorts(env = process.env) {
  const ports = [...CONTROLLER_PORTS, ...CONTROLLER_PORT_ENV.map(name => env[name])]
  const directory = webDirectory(env)
  if (directory) try { ports.push(...readFileSync(join(directory, 'controller-ports'), 'utf8').split(/\s+/)) } catch {}
  return new Set(ports.map(Number).filter(port => Number.isSafeInteger(port) && port > 0))
}
function projectOrigins(env = process.env) {
  const directory = webDirectory(env)
  const port = env.APP_PORT || 3000
  const urls = [`http://localhost:${port}`, `http://127.0.0.1:${port}`, `http://[::1]:${port}`]
  if (env.APP_URL) urls.push(env.APP_URL)
  if (directory) {
    try { urls.push(readFileSync(join(directory, 'app-url'), 'utf8').trim()) } catch {}
    try { urls.push(...JSON.parse(readFileSync(join(directory, 'project-preview-origins.json'), 'utf8'))) } catch {}
  }
  return new Set(urls.flatMap(url => { try { return [new URL(url).origin] } catch { return [] } }))
}
// Returns '' for project pages, otherwise the skip reason.
function skipReason(url, env = process.env) {
  let parsed
  try { parsed = new URL(url) } catch { return 'invalid page URL' }
  if (!/^https?:$/.test(parsed.protocol)) return 'non-HTTP page'
  if (projectOrigins(env).has(parsed.origin)) return ''
  if (LOOPBACK_HOSTS.has(parsed.hostname)) {
    const port = Number(parsed.port || (parsed.protocol === 'https:' ? 443 : 80))
    return controllerPorts(env).has(port) ? 'controller port' : ''
  }
  return 'origin not a project preview'
}
function isProjectPage(url, env = process.env) { return !skipReason(url, env) }
function safeOrigin(url) { try { const parsed = new URL(url); return /^https?:$/.test(parsed.protocol) ? parsed.origin : parsed.protocol } catch { return 'invalid' } }
function logSkip(reason, url, env) {
  const line = `WIP screenshot skipped: ${reason} (${safeOrigin(url)})`
  console.error(line)
  const web = webDirectory(env)
  if (web) try { appendFileSync(join(web, 'wip-capture.log'), `${new Date().toISOString()} ${line}\n`) } catch {}
}
function imageType(bytes) {
  if (bytes.subarray(0, 8).toString('hex') === '89504e470d0a1a0a') return 'image/png'
---CLI---
playwright-cli - run playwright mcp commands from terminal

Usage: playwright-cli <command> [args] [options]
Usage: playwright-cli -s=<session> <command> [args] [options]

Core:
  open [url]                  open the browser
  attach [name]               attach to a running playwright browser
  close                       close the browser
  detach                      detach from an attached browser
  goto <url>                  navigate to a url
  type <text>                 type text into editable element
  click <target> [button]     perform click on a web page
  dblclick <target> [button]  perform double click on a web page
  fill <target> <text>        fill text into editable element
  drag <startTarget> <endTarget> perform drag and drop between two elements
  drop <target>               drop files or data onto an element
  hover <target>              hover over element on page
  select <target> <val>       select an option in a dropdown
  upload <files...>           upload one or multiple files
  check <target>              check a checkbox or radio button
  uncheck <target>            uncheck a checkbox or radio button
  snapshot [target]           capture page snapshot to obtain element ref
  find [text]                 search the page snapshot for text or a regexp, returning matching nodes with surrounding context (like search snippets)
  eval <func> [target]        evaluate javascript expression on page or element
  dialog-accept [prompt]      accept a dialog
  dialog-dismiss              dismiss a dialog
  resize <w> <h>              resize the browser window
  delete-data                 delete session data

Navigation:
  go-back                     go back to the previous page
  go-forward                  go forward to the next page
  reload                      reload the current page

Keyboard:
  press <key>                 press a key on the keyboard, `a`, `arrowleft`
  keydown <key>               press a key down on the keyboard
  keyup <key>                 press a key up on the keyboard

