:root {
  --amber: #ffb340;
  --amber-dim: #c9802a;
  --red: #ff453a;
  --cyan: #57d6ff;
  --green: #57e08a;
  --panel: rgba(10, 13, 16, 0.66);
  --panel-edge: rgba(255, 255, 255, 0.09);
  --ink: #f2f5f7;
  --ink-dim: #98a3ad;
  --font: "Inter", "Helvetica Neue", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
}
* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; overflow: hidden; background: #07090b; color: var(--ink); font-family: var(--font); -webkit-font-smoothing: antialiased; }
#app { position: fixed; inset: 0; }
#scene { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }

#vignette {
  position: absolute; inset: 0; pointer-events: none;
  background:
    radial-gradient(120% 90% at 50% 45%, rgba(0,0,0,0) 42%, rgba(0,0,0,0.42) 100%),
    linear-gradient(180deg, rgba(0,0,0,0.35) 0%, rgba(0,0,0,0) 18%, rgba(0,0,0,0) 72%, rgba(0,0,0,0.42) 100%);
  transition: background 0.4s ease;
}
body.slowmo #vignette { background: radial-gradient(120% 90% at 50% 45%, rgba(0,0,0,0) 30%, rgba(10,20,40,0.62) 100%); }

#speedlines {
  position: absolute; inset: 0; pointer-events: none; opacity: 0;
  background: radial-gradient(60% 50% at 50% 50%, rgba(255,255,255,0) 55%, rgba(180,220,255,0.13) 100%);
  transition: opacity 0.25s ease;
}

#hud { position: absolute; inset: 0; pointer-events: none; transition: opacity 0.25s ease; }
#hud.hidden { opacity: 0; }
.panel {
  position: absolute;
  background: linear-gradient(180deg, rgba(16,20,25,0.78), rgba(8,10,13,0.72));
