  backdrop-filter: blur(9px) saturate(120%);
}
.panel::before {
  content: ""; position: absolute; left: 0; top: 0; width: 26px; height: 2px;
  background: var(--amber); box-shadow: 0 0 12px rgba(255,179,64,0.7);
}

/* ---------- vehicle panel ---------- */
.vehicle-panel { left: 20px; top: 20px; width: 300px; padding: 13px 15px 11px; }
.vp-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }
