.vp-dmg.warn { color: var(--amber); }
.vp-dmg.bad { color: var(--red); text-shadow: 0 0 16px rgba(255,69,58,0.6); }
.bars { margin: 11px 0 9px; display: grid; gap: 5px; }
.bar-row { display: grid; grid-template-columns: 62px 1fr 26px; align-items: center; gap: 8px; }
.bar-row span { font-size: 8.5px; letter-spacing: 0.14em; color: #8e9aa4; }
