/* ---------- minimap ---------- */
.minimap-panel { right: 20px; bottom: 20px; width: 190px; padding: 8px; }
#minimap { display: block; width: 174px; height: 174px; border-radius: 2px; background: rgba(4,6,8,0.7); }
.mm-label { margin-top: 6px; font-size: 7.5px; letter-spacing: 0.14em; color: #74808a; text-align: center; }

