kbd {
  font-family: var(--font); font-size: 9px; font-weight: 700; color: #dbe3e9;
  background: rgba(255,255,255,0.09); border: 1px solid rgba(255,255,255,0.13);
  border-bottom-color: rgba(0,0,0,0.4); border-radius: 2px; padding: 1px 4px; letter-spacing: 0;
