150:     this.frame = { fwd: { x: 0, y: 0, z: 1 }, right: { x: 1, y: 0, z: 0 }, up: { x: 0, y: 1, z: 0 } };
151:     this.gforce = { x: 0, y: 0, z: 0, peak: 0 };
152:     this._prevVel = { x: 0, y: 0, z: 0 };
153:     this._accelSmooth = { x: 0, y: 0, z: 0 };
154:     this.speed = 0;
155:     this.speedKph = 0;
156:     this.forwardSpeed = 0;
157:     this.airTime = 0;
158:     this.grounded = 0;
159:     this.impactCooldown = 0;
160:     this.crashScore = 0;
161:     this.scrapeTimer = 0;
162:     this.wheelDamageAccum = 0;
163:     this.spawned = false;
164:     this.lap = { airStart: 0, airY: 0, jumping: false, jumpStartZ: 0, jumpStartX: 0 };
165:     this.events = [];
166:     this.build();
167:   }
168: 
169:   build() {
170:     const spec = this.spec;
171:     const stations = resample(generatorStations({ ...spec.shape, mass: spec.mass }), LOOPS);
172:     this.stations = stations;
173:     const body = this.body;
174:     const nodeMassBase = spec.mass;
175: 
176:     // 1. nodes
177:     for (let i = 0; i < LOOPS; i++) {
178:       const st = stations[i];
179:       const ring = [];
180:       const top = (st.roof + st.belt) * 0.5;
181:       for (let j = 0; j < RING; j++) {
182:         let x, y;
183:         switch (j) {
184:           case 0: x = -st.gw * 0.44; y = st.roof; break;
185:           case 1: x = -st.gw; y = st.roof - 0.075; break;
186:           case 2: x = -st.bw; y = st.belt; break;
187:           case 3: x = -st.rw; y = st.rocker; break;
188:           case 4: x = -st.fw; y = st.floor; break;
189:           case 5: x = st.fw; y = st.floor; break;
190:           case 6: x = st.rw; y = st.rocker; break;
191:           case 7: x = st.bw; y = st.belt; break;
192:           case 8: x = st.gw; y = st.roof - 0.075; break;
193:           default: x = st.gw * 0.44; y = st.roof; break;
194:         }
195:         // structural weight: roof light, floor/sills heavy
196:         let w = 1.0;
197:         if (y > top) w = 0.52;
198:         else if (y > st.belt - 0.05) w = 0.9;
199:         else if (y < st.rocker + 0.02) w = 1.15;
200:         ring.push({ idx: -1, w, x, y, z: st.z });
201:       }
202:       this.rings.push(ring);
203:       this.grid.push(ring.map(() => -1));
204:     }
205:     // mass normalisation
206:     let wsum = 0;
207:     for (const ring of this.rings) for (const p of ring) wsum += p.w;
208:     const spineW = LOOPS * 1.6;
209:     wsum += spineW;
210:     const unit = nodeMassBase / wsum;
211: 
212:     for (let i = 0; i < LOOPS; i++) {
213:       const ring = this.rings[i];
214:       for (let j = 0; j < RING; j++) {
215:         const p = ring[j];
216:         const idx = body.addNode(p.x, p.y, p.z, p.w * unit, 1);
217:         this.grid[i][j] = idx;
218:         p.idx = idx;
219:       }
220:       const st = stations[i];
221:       const sidx = body.addNode(0, st.floor + 0.14, st.z, 1.6 * unit, 2);
222:       this.spine.push(sidx);
223:     }
224: 
225:     // 2. beams
226:     const half = spec.shape.half;
227:     const frontZ = spec.wheel.frontZ;
228:     const rearZ = spec.wheel.rearZ;
229:     const zoneOf = (z) => (z > frontZ - 0.30 ? 'front' : z < rearZ + 0.30 ? 'rear' : 'cabin');
230:     const cfg = (zone, kind) => {
231:       if (zone === 'front' || zone === 'rear') {
232:         return { compliance: 5.5e-8, yield: 0.016, maxStrain: 0.34 };
233:       }
234:       if (kind === 'roof') return { compliance: 4.2e-8, yield: 0.024, maxStrain: 0.62 };
235:       return { compliance: 2.4e-8, yield: 0.030, maxStrain: 0.85 };
236:     };
237: 
238:     for (let i = 0; i < LOOPS; i++) {
239:       const ring = this.rings[i];
240:       const zone = zoneOf(stations[i].z);
241:       // perimeter
242:       for (let j = 0; j < RING; j++) {
243:         const a = ring[j].idx, b = ring[(j + 1) % RING].idx;
244:         const isTop = j === 0 || j === 8 || j === 9;
245:         const c = cfg(zone, isTop ? 'roof' : 'side');
246:         const bm = body.addBeam(a, b, { ...c, group: zone });
247:         bm.zone = zone;
248:       }
249:       // spine ties
250:       for (let j = 0; j < RING; j++) {
251:         if (j === 4 || j === 5 || j === 3 || j === 6) {
252:           const c = cfg(zone, 'floor');
253:           const bm = body.addBeam(ring[j].idx, this.spine[i], { ...c, group: zone, compliance: c.compliance * 0.8 });
254:           bm.zone = zone;
255:         }
256:       }
257:     }
258:     for (let i = 0; i < LOOPS - 1; i++) {
259:       const A = this.rings[i], B = this.rings[i + 1];
260:       const zone = zoneOf((stations[i].z + stations[i + 1].z) * 0.5);
261:       for (let j = 0; j < RING; j++) {
262:         const isTop = j === 0 || j === 1 || j === 8 || j === 9;
263:         const c = cfg(zone, isTop ? 'roof' : 'side');
264:         const bm = body.addBeam(A[j].idx, B[j].idx, { ...c, group: zone });
265:         bm.zone = zone;
266:       }
267:       // diagonals alternate
268:       for (let j = 0; j < RING; j++) {
269:         const jn = (j + 1) % RING;
270:         const c = cfg(zone, 'diag');
271:         const bm = (i + j) % 2 === 0
272:           ? body.addBeam(A[j].idx, B[jn].idx, { ...c, compliance: c.compliance * 1.5, group: zone })
273:           : body.addBeam(A[jn].idx, B[j].idx, { ...c, compliance: c.compliance * 1.5, group: zone });
274:         bm.zone = zone;
275:       }
276:       const sbm = body.addBeam(this.spine[i], this.spine[i + 1], { ...cfg(zone, 'side'), group: zone });
277:       sbm.zone = zone;
278:     }
279:     // floor X bracing at every other ring for torsional stiffness
280:     for (let i = 0; i < LOOPS - 1; i += 1) {
281:       const A = this.rings[i], B = this.rings[i + 1];
282:       const zone = zoneOf((stations[i].z + stations[i + 1].z) * 0.5);
283:       const c = cfg(zone, 'floor');
284:       body.addBeam(A[4].idx, B[5].idx, { ...c, compliance: c.compliance * 2.0, group: zone });
285:       body.addBeam(A[5].idx, B[4].idx, { ...c, compliance: c.compliance * 2.0, group: zone });
286:     }
287: 
288:     // 3. wheels
289:     const spec2 = spec.wheel;
290:     const defs = [
291:       { name: 'FL', x: -spec2.track, z: spec2.frontZ, steer: true, driveShare: spec.drive === 'RWD' ? 0 : spec.drive === 'FWD' ? 0.5 : 0.25 },
292:       { name: 'FR', x: spec2.track, z: spec2.frontZ, steer: true, driveShare: spec.drive === 'RWD' ? 0 : spec.drive === 'FWD' ? 0.5 : 0.25 },
293:       { name: 'RL', x: -spec2.track, z: spec2.rearZ, steer: false, driveShare: spec.drive === 'FWD' ? 0 : spec.drive === 'RWD' ? 0.5 : 0.25 },
294:       { name: 'RR', x: spec2.track, z: spec2.rearZ, steer: false, driveShare: spec.drive === 'FWD' ? 0 : spec.drive === 'RWD' ? 0.5 : 0.25 },
295:     ];
296:     for (const def of defs) {
297:       const attach = this.findAttach(def.x, def.z, 9);
298:       const anchor = this.centroid(attach);
299:       const wheel = {
300:         ...def, attach,
301:         anchorLocal: { x: anchor.x, y: anchor.y, z: anchor.z },
302:         ax: anchor.x, ay: anchor.y, az: anchor.z,
303:         cx: anchor.x, cz: anchor.z,
304:         radius: spec2.radius, width: spec2.width,
305:         omega: 0, spin: 0, steerAngle: 0, compression: 0, prevCompression: 0,
306:         contact: false, contactY: 0, load: 0, slip: 0, longSlip: 0, latSlip: 0,
307:         damage: 0, hubY: 0, hubX: 0, hubZ: 0, spinVel: 0, restLen: 0.6, maxTravel: spec.travel,
308:         lastImpact: 0, dirt: 0, locked: false,
309:       };
310:       this.wheels.push(wheel);
311:     }
312: 
313:     this.solver = new PhysicsSolver(body, null);
314:     this.solver.h = 1 / 240;
315:     this.solver.iterations = 4;
316:   }
317: 
318:   findAttach(lx, lz, count) {
319:     const st = this.stations;
320:     // nearest nodes in the plane, weighted by distance
321:     const cand = [];
322:     for (let i = 0; i < LOOPS; i++) {
323:       for (let j = 0; j < RING; j++) {
324:         const p = this.rings[i][j];
325:         const dist = Math.hypot(p.x - lx, p.y - 0.72, p.z - lz);
326:         cand.push({ idx: p.idx, d: dist });
327:       }
328:       const s = this.spine[i];
329:       void s;
330:     }
331:     cand.sort((a, b) => a.d - b.d);
332:     const top = cand.slice(0, count);
333:     let wsum = 0;
334:     for (const c of top) { c.w = 1 / (c.d + 0.12) ** 2; wsum += c.w; }
335:     return top.map((c) => ({ i: c.idx, w: c.w / wsum }));
336:   }
337: 
338:   centroid(attach) {
339:     let x = 0, y = 0, z = 0;
340:     for (const a of attach) {
341:       const n = this.body.nodes[a.i];
342:       x += n.x * a.w; y += n.y * a.w; z += n.z * a.w;
343:     }
344:     return { x, y, z };
345:   }
346: 
347:   // ------------------------------------------------------------------
348:   place(x, z, yaw, getGroundY) {
349:     const cos = Math.cos(yaw), sin = Math.sin(yaw);
350:     const nodes = this.body.nodes;
351:     for (const ring of this.rings) {
352:       for (const p of ring) {
353:         const n = nodes[p.idx];
354:         const gy = getGroundY(x + p.x * cos + p.z * sin, z - p.x * sin + p.z * cos);
355:         n.x = x + p.x * cos + p.z * sin;
356:         n.y = gy + p.y + 0.06;
357:         n.z = z - p.x * sin + p.z * cos;
358:         n.px = n.x; n.py = n.y; n.pz = n.z;
359:         n.vx = n.vy = n.vz = 0;
360:       }
361:       const s = nodes[this.spine[ring === this.rings[this.rings.length - 1] ? LOOPS - 1 : 0]];
362:       void s;
363:     }
364:     for (let i = 0; i < LOOPS; i++) {
365:       const st = this.stations[i];
366:       const n = nodes[this.spine[i]];
367:       const wx = x + 0 * cos + st.z * sin;
368:       const wz = z - 0 * sin + st.z * cos;
369:       n.x = wx; n.z = wz;
370:       n.y = getGroundY(wx, wz) + st.floor + 0.14 + 0.06;
371:       n.px = n.x; n.py = n.y; n.pz = n.z;
372:       n.vx = n.vy = n.vz = 0;
373:     }
374:     for (const beam of this.body.beams) { beam.rest = beam.rest0; beam.plastic = 0; beam.broken = false; beam.lambda = 0; }
375:     this.spawnPos = { x, z, yaw };
376:     this.damage = { body: 0, engine: 0, wheels: 0, chassis: 0, overall: 0 };
377:     for (const w of this.wheels) {
378:       w.omega = 0; w.spin = 0; w.damage = 0; w.compression = 0; w.prevCompression = 0; w.locked = false;
379:     }
380:     this.engine.gear = 1; this.engine.targetGear = 1; this.engine.rpm = this.spec.idle;
381:     this.engine.damage = 0; this.engine.running = true; this.engine.stall = 0; this.engine.shiftTimer = 0;
382:     this.engine.boost = 0;
383:     this.crashScore = 0;
384:     this.steer = 0;
385:     this.spawned = true;
386:     this.airTime = 0;
387:     this.gforce.peak = 0;
388:     this.calibrateSuspension(getGroundY);
389:   }
390: 
391:   calibrateSuspension(getGroundY) {
392:     const gy = getGroundY(this.spawnPos.x, this.spawnPos.z);
393:     for (const w of this.wheels) {
394:       const a = this.centroid(w.attach);
395:       w.anchorLocal = { x: a.x, y: a.y, z: a.z };
396:       const gap = a.y - (gy + w.radius);
397:       w.restLen = gap + 0.11;
398:       w.hubY = gy + w.radius;
399:     }
400:   }
401: 
402:   setColliders(colliders) {
403:     this.colliders = colliders;
404:     this.solver.colliders = colliders;
405:   }
406: 
407:   // ------------------------------------------------------------------
408:   computeFrame() {
409:     const nodes = this.body.nodes;
410:     const g = this.grid;
411:     const iF = Math.min(LOOPS - 1, 15);
412:     const iR = 3;
413:     const fl = nodes[g[iF][2]], fr = nodes[g[iF][7]];
414:     const rl = nodes[g[iR][2]], rr = nodes[g[iR][7]];
415:     const fcx = (fl.x + fr.x) * 0.5, fcy = (fl.y + fr.y) * 0.5, fcz = (fl.z + fr.z) * 0.5;
416:     const rcx = (rl.x + rr.x) * 0.5, rcy = (rl.y + rr.y) * 0.5, rcz = (rl.z + rr.z) * 0.5;
417:     let fx = fcx - rcx, fy = fcy - rcy, fz = fcz - rcz;
418:     let len = Math.hypot(fx, fy, fz) || 1;
419:     fx /= len; fy /= len; fz /= len;
420:     let rx = fr.x - fl.x, ry = fr.y - fl.y, rz = fr.z - fl.z;
421:     len = Math.hypot(rx, ry, rz) || 1;
422:     rx /= len; ry /= len; rz /= len;
423:     // up = fwd x right
424:     let ux = fy * rz - fz * ry, uy = fz * rx - fx * rz, uz = fx * ry - fy * rx;
425:     len = Math.hypot(ux, uy, uz) || 1;
426:     ux /= len; uy /= len; uz /= len;
427:     // re-orthogonalise right
428:     rx = uy * fz - uz * fy; ry = uz * fx - ux * fz; rz = ux * fy - uy * fx;
429:     len = Math.hypot(rx, ry, rz) || 1;
430:     rx /= len; ry /= len; rz /= len;
431:     this.frame.fwd = { x: fx, y: fy, z: fz };
432:     this.frame.right = { x: rx, y: ry, z: rz };
433:     this.frame.up = { x: ux, y: uy, z: uz };
434:   }
435: 
436:   forwardSpeedKph() {
437:     const v = this.body.velocity();
438:     const f = this.frame.fwd;
439:     return (v.x * f.x + v.z * f.z) * 3.6;
440:   }
441: 
442:   // main per-substep control + wheel force application
443:   applyControls(h, input) {
444:     if (!this.spawned) return;
445:     this.computeFrame();
446:     const spec = this.spec;
447:     const nodes = this.body.nodes;
448:     const eng = this.engine;
449:     const vel = this.body.velocity();
450:     const fwdSpeed = vel.x * this.frame.fwd.x + vel.z * this.frame.fwd.z;
451:     const speed = vel.speed;
452:     this.speed = speed;
453:     this.forwardSpeed = fwdSpeed;
454: 
455:     // steering
456:     const steerMax = lerp(0.61, 0.115, clamp(Math.abs(fwdSpeed) / 46, 0, 1));
457:     const target = input.steer * steerMax;
458:     this.steer += (target - this.steer) * Math.min(1, h * 9.0);
459:     this.steer = clamp(this.steer, -steerMax, steerMax);
460: 
461:     // pedals
462:     const throttle = input.throttle;
463:     const brake = input.brake;
464:     const handbrake = input.handbrake;
465: 
466:     // ---- engine ----
467:     eng.throttle += (throttle - eng.throttle) * Math.min(1, h * 14);
468:     const gear = eng.gear;
469:     const gearRatio = gear === 0 ? 0 : gear > 0 ? spec.gears[gear - 1] : 3.4;
470:     const totalRatio = gearRatio * spec.final;
471:     const driven = this.wheels.filter((w) => w.driveShare > 0);
472:     let wheelOmega = 0;
473:     if (driven.length) {
474:       for (const w of driven) wheelOmega += w.omega * w.driveShare;
475:       wheelOmega /= driven.reduce((a, w) => a + w.driveShare, 0);
476:     }
477:     const rpmFromWheels = Math.abs(wheelOmega) * Math.abs(totalRatio) * 60 / (2 * Math.PI);
478:     if (eng.shiftTimer > 0) eng.shiftTimer -= h;
479:     if (eng.stall > 0) eng.stall -= h;
480: 
481:     let rpmTarget;
482:     if (gear === 0) rpmTarget = spec.idle + eng.throttle * (spec.redline - spec.idle) * 0.92;
483:     else if (gear < 0) rpmTarget = spec.idle + Math.abs(fwdSpeed) * 90 * 0.35 + eng.throttle * 900;
484:     else rpmTarget = Math.max(spec.idle + eng.throttle * 700, Math.min(rpmFromWheels, spec.redline * 1.02));
485:     if (Math.abs(fwdSpeed) < 1.0 && gear > 0) rpmTarget = Math.max(rpmTarget, spec.idle + eng.throttle * 2400);
486:     eng.rpm += (rpmTarget - eng.rpm) * Math.min(1, h * 8.5);
487:     eng.rpm = clamp(eng.rpm, 0, spec.redline * 1.06);
488: 
489:     // turbo lag
490:     const boostTarget = eng.throttle * clamp((eng.rpm - 1600) / 2200, 0, 1);
491:     eng.boost += (boostTarget - eng.boost) * Math.min(1, h * (boostTarget > eng.boost ? 2.6 : 6.5));
492:     const boostMul = 1 + eng.boost * 0.45;
493: 
494:     let torque = torqueCurve(eng.rpm, spec.redline, spec.torque) * eng.throttle * boostMul;
495:     if (eng.shiftTimer > 0) torque = 0;
496:     if (eng.shiftFlash > 0) eng.shiftFlash -= h;
497: 
498:     // engine braking + rev limiter
499:     if (eng.rpm > spec.redline * 1.005) torque = -spec.torque * 0.06;
500:     if (eng.throttle < 0.05 && Math.abs(fwdSpeed) > 1 && gear > 0) torque -= spec.torque * 0.055 * clamp(eng.rpm / spec.redline, 0, 1);
501: 
502:     eng.damage = this.damage.engine;
503:     if (eng.damage > 0.92) { eng.running = false; }
504:     if (!eng.running) { torque = 0; }
505:     torque *= 1 - eng.damage * 0.85;
506: 
507:     // automatic gearbox
508:     if (gear > 0 && eng.shiftTimer <= 0) {
509:       const upRpm = spec.redline * 0.93;
510:       if (eng.rpm > upRpm && gear < spec.gears.length) this.shift(1, h);
511:       else if (eng.rpm < spec.redline * 0.32 && gear > 1) this.shift(-1, h);
512:     }
513:     // reverse / drive selection
514:     if (gear <= 0) {
515:       if (throttle > 0.15 && fwdSpeed > -0.6) { eng.gear = 1; eng.shiftTimer = 0.25; }
516:       if (gear < 0 && fwdSpeed > 1.0) eng.gear = 1;
517:     } else if (brake > 0.5 && fwdSpeed < 0.55 && fwdSpeed > -1.5 && throttle < 0.1) {
518:       // brake held at standstill -> reverse
519:       if (eng.stillTimer === undefined) eng.stillTimer = 0;
520:       eng.stillTimer += h;
521:       if (eng.stillTimer > 0.35) { eng.gear = -1; eng.shiftTimer = 0.2; eng.stillTimer = 0; }
522:     } else eng.stillTimer = 0;
523:     if (gear === -1 && throttle > 0.05) {
524:       // reverse throttle drives backwards
525:     }
526: 
527:     eng.torqueOut = torque;
528:     const dir = gear < 0 ? -1 : 1;
529:     const axleTorque = torque * Math.abs(totalRatio) * 0.9 * dir;
530:     eng.driveTorque = axleTorque;
531: 
532:     // brake torque
533:     const brakeTorque = brake * spec.brake * (gear < 0 ? 0.7 : 1) + (handbrake ? spec.brake * 0.85 : 0);
534: 
535:     // ---- wheels ----
536:     const throttleCut = eng.shiftTimer > 0 ? 0 : 1;
537:     for (const w of this.wheels) {
538:       // anchor from attached nodes
539:       const c = this.centroid(w.attach);
540:       w.ax = c.x; w.ay = c.y; w.az = c.z;
541:       w.cx = c.x; w.cz = c.z;
542: 
543:       const up = this.frame.up;
544:       // vertical gap to ground
545:       const gy = this.colliders ? this.colliders.surfaceHeight(c.x, c.z, w.ay + 0.05) : 0;
546:       let L = w.ay - gy - w.radius;
547:       const airborne = L > w.restLen;
548:       const comp = airborne ? 0 : clamp(w.restLen - L, 0, w.maxTravel);
549:       w.compression = comp;
550:       const compVel = (comp - w.prevCompression) / h;
551:       w.prevCompression = comp;
552: 
553:       // suspension force
554:       const gripFactor = 1 - w.damage * 0.45;
555:       let springF = comp * spec.spring * gripFactor;
556:       // bump stop
557:       if (comp >= w.maxTravel - 0.005) springF += (comp - w.maxTravel + 0.005) * spec.spring * 7;
558:       let dampF = compVel * spec.damper;
559:       dampF = clamp(dampF, -spec.spring * 0.9, spec.spring * 0.9);
560:       let N = Math.max(0, springF + dampF);
561:       N = Math.min(N, spec.mass * 26);
562:       w.load = N;
563:       w.contact = !airborne && comp > 0.001;
564:       w.hubY = w.contact ? gy + w.radius : w.ay - w.restLen;
565:       w.hubX = c.x; w.hubZ = c.z;
566:       w.contactY = gy;
567: 
568:       if (w.contact) {
569:         // apply spring along body up at the arch
570:         for (const a of w.attach) {
571:           const n = nodes[a.i];
572:           n.fx += up.x * N * a.w;
573:           n.fy += up.y * N * a.w;
574:           n.fz += up.z * N * a.w;
575:         }
576:         // lateral grip / slip
577:         const f = this.frame.fwd, r = this.frame.right;
578:         const steerA = w.steer ? this.steer * (w.x < 0 ? 1.0 : 1.0) : 0;
579:         w.steerAngle = steerA;
580:         const cs = Math.cos(steerA), sn = Math.sin(steerA);
581:         const wfx = f.x * cs + r.x * sn, wfz = f.z * cs + r.z * sn;
582:         const wrx = r.x * cs - f.x * sn, wrz = r.z * cs - f.z * sn;
583:         // chassis velocity at the wheel
584:         let cvx = 0, cvz = 0;
