28:     const u = i / (N - 1);            // 0 rear -> 1 front
29:     const z = (u * 2 - 1) * half;
30:     const zn = u * 2 - 1;             // -1..1
31:     // cabin mask: 1 inside greenhouse
32:     const frontMask = smoothstep(cabinFront + 0.24, cabinFront - 0.12, zn);
33:     const rearMask = smoothstep(cabinRear - 0.22, cabinRear + 0.10, zn);
34:     const cab = frontMask * rearMask;
35:     // hood/deck baseline height (front and rear are lower than the belt)
36:     const baseTop = lerp(hood, hood - noseDrop, smoothstep(0.2, 1, zn));
37:     const rearTop = lerp(hood, hood - tailDrop, smoothstep(-0.2, -1, zn));
38:     const lowTop = zn > 0 ? baseTop : rearTop;
39:     const crown = 0.035 * Math.sin(Math.PI * clamp((zn - cabinRear) / (cabinFront - cabinRear), 0, 1));
40:     const roofY = lowTop + (roof - lowTop) * cab + crown * cab;
41:     const beltY = belt - 0.10 * Math.pow(Math.abs(zn), 2.6) - 0.04 * (1 - cab) * 0;
42:     const floorY = floor + 0.10 * Math.pow(Math.abs(zn), 3.2) + 0.02;
43:     const rockerY = floorY + 0.115;
44:     const bw = width * 0.5 * (0.94 - 0.055 * zn * zn);
45:     const rw = bw * 0.815;
46:     const fw = bw * 0.66;
47:     const gw = bw * (0.6 + 0.36 * (1 - cab));
48:     stations.push({
49:       z, floor: floorY, rocker: rockerY, belt: Math.max(beltY, floorY + 0.28),
50:       roof: Math.max(roofY, beltY + 0.06), fw, rw, bw, gw,
51:     });
52:   }
