269: export class PhysicsSolver {
270:   constructor(body, colliders) {
271:     this.body = body;
272:     this.colliders = colliders;
273:     this.h = 1 / 240;
274:     this.iterations = 4;
275:     this.airDrag = 0.0;
276:     this.impactSpeed = 0;
277:     this.maxPenetration = 0;
278:     this.time = 0;
279:   }
280: 
281:   step(substeps = 1) {
282:     const body = this.body;
283:     const h = this.h;
284:     const invH2 = 1 / (h * h);
285:     this.impactSpeed = 0;
286:     for (let s = 0; s < substeps; s++) {
287:       this.time += h;
288:       // integrate
289:       for (const n of body.nodes) {
290:         n.px = n.x; n.py = n.y; n.pz = n.z;
291:         if (n.invMass === 0) continue;
292:         n.vx += (n.fx * n.invMass) * h;
293:         n.vy += (GRAVITY + n.fy * n.invMass) * h;
294:         n.vz += (n.fz * n.invMass) * h;
295:         // gentle numerical damping
296:         n.vx *= 0.9998; n.vy *= 0.9998; n.vz *= 0.9998;
297:         n.x += n.vx * h; n.y += n.vy * h; n.z += n.vz * h;
298:         n.fx = n.fy = n.fz = 0;
299:         n.grounded = 0; n.contact = 0;
300:       }
301:       // constraints
302:       for (const b of body.beams) b.lambda = 0;
303:       for (let it = 0; it < this.iterations; it++) {
304:         this.solveBeams(invH2);
305:       }
306:       // static collisions
307:       for (const n of body.nodes) {
308:         const imp = this.colliders.resolveNode(n, h);
309:         if (imp > this.impactSpeed) this.impactSpeed = imp;
310:       }
311:       // plastic yield (once per substep, after constraints)
312:       this.yieldBeams();
313:       // velocity update
314:       const invH = 1 / h;
315:       for (const n of body.nodes) {
316:         if (n.invMass === 0) { n.vx = n.vy = n.vz = 0; continue; }
317:         n.vx = (n.x - n.px) * invH;
318:         n.vy = (n.y - n.py) * invH;
319:         n.vz = (n.z - n.pz) * invH;
320:         // clamp insane velocities for stability
321:         const sp = Math.hypot(n.vx, n.vy, n.vz);
322:         const MAX = 160;
323:         if (sp > MAX) { const k = MAX / sp; n.vx *= k; n.vy *= k; n.vz *= k; }
324:       }
325:       // beam axis damping (removes ringing)
326:       this.dampBeams(h);
327:     }
328:   }
329: 
330:   solveBeams(invH2) {
331:     const nodes = this.body.nodes, beams = this.body.beams;
332:     for (let i = 0; i < beams.length; i++) {
333:       const b = beams[i];
334:       if (b.broken) continue;
335:       const A = nodes[b.a], B = nodes[b.b];
336:       const w = A.invMass + B.invMass;
337:       if (w === 0) continue;
338:       let dx = B.x - A.x, dy = B.y - A.y, dz = B.z - A.z;
339:       const len = Math.sqrt(dx * dx + dy * dy + dz * dz);
340:       if (len < 1e-8) continue;
341:       const C = len - b.rest;
342:       const alpha = b.compliance * invH2;
343:       const dl = (-C - alpha * b.lambda) / (w + alpha);
344:       b.lambda += dl;
345:       const k = dl / len;
346:       const ax = dx * k, ay = dy * k, az = dz * k;
347:       if (A.invMass) { A.x -= ax * A.invMass; A.y -= ay * A.invMass; A.z -= az * A.invMass; }
348:       if (B.invMass) { B.x += ax * B.invMass; B.y += ay * B.invMass; B.z += az * B.invMass; }
349:     }
350:   }
351: 
352:   yieldBeams() {
353:     for (const b of this.body.beams) {
354:       if (b.broken) continue;
355:       const A = this.body.nodes[b.a], B = this.body.nodes[b.b];
356:       const dx = B.x - A.x, dy = B.y - A.y, dz = B.z - A.z;
357:       const len = Math.sqrt(dx * dx + dy * dy + dz * dz);
358:       const strain = (len - b.rest) / b.rest;
359:       if (Math.abs(strain) > b.yield) {
360:         const excess = (Math.abs(strain) - b.yield) * Math.sign(strain);
361:         // plastic flow: rest length chases current length
362:         const flow = excess * 0.055;
363:         b.rest += b.rest * flow;
364:         b.plastic += Math.abs(flow);
365:         // broken beams: fully separate the shell
366:         if (Math.abs(strain) > b.maxStrain) {
367:           b.broken = true;
368:         }
369:       }
370:       if (b.plastic > 0.9) b.broken = true;
371:     }
372:   }
373: 
374:   dampBeams(h) {
375:     const nodes = this.body.nodes;
376:     for (const b of this.body.beams) {
377:       if (b.broken) continue;
378:       const A = nodes[b.a], B = nodes[b.b];
379:       let dx = B.x - A.x, dy = B.y - A.y, dz = B.z - A.z;
380:       const len = Math.sqrt(dx * dx + dy * dy + dz * dz) || 1e-6;
381:       dx /= len; dy /= len; dz /= len;
382:       const rel = (B.vx - A.vx) * dx + (B.vy - A.vy) * dy + (B.vz - A.vz) * dz;
383:       const damp = clamp(rel * 2.2, -3, 3) * h * 40;
384:       const wa = A.invMass, wb = B.invMass, w = wa + wb || 1;
385:       A.vx += dx * damp * (wa / w); A.vy += dy * damp * (wa / w); A.vz += dz * damp * (wa / w);
386:       B.vx -= dx * damp * (wb / w); B.vy -= dy * damp * (wb / w); B.vz -= dz * damp * (wb / w);
387:     }
388:   }
389: }
