395:   // returns normalised force (-1..1) with a peak then falloff
396:   const a = Math.abs(slip);
397:   let f;
398:   if (a < peak) f = a / peak;
399:   else f = 1 - 0.34 * Math.min(1, (a - peak) / 0.55);
400:   return Math.sign(slip) * f * mu;
401: }
