404:   const a = Math.abs(alpha);
405:   let f;
406:   if (a < peak) f = a / peak;
407:   else f = 1 - 0.22 * Math.min(1, (a - peak) / 0.5);
408:   return -Math.sign(alpha) * f * mu;
409: }
