56: // Resample stations down to LOOPS control rings, keeping ends exact.
57: function resample(stations, count) {
58:   const out = [];
59:   const keys = ['z', 'floor', 'rocker', 'belt', 'roof', 'fw', 'rw', 'bw', 'gw'];
60:   const n = stations.length;
61:   for (let i = 0; i < count; i++) {
62:     const s = (i / (count - 1)) * (n - 1);
63:     const i1 = Math.floor(s);
64:     const i2 = Math.min(n - 1, i1 + 1);
65:     const t = s - i1;
66:     const i0 = Math.max(0, i1 - 1), i3 = Math.min(n - 1, i2 + 1);
67:     const st = {};
68:     for (const k of keys) st[k] = catmull(stations[i0][k], stations[i1][k], stations[i2][k], stations[i3][k], t);
69:     out.push(st);
70:   }
71:   return out;
72: }
