394: export function tireLongitudinal(slip, peak = 0.13, mu = 1) {
395:   // returns normalised force (-1..1) with a peak then falloff
396:   const a = Math.abs(slip);
397:   let f;
398:   if (a < peak) f = a / peak;
399:   else f = 1 - 0.34 * Math.min(1, (a - peak) / 0.55);
400:   return Math.sign(slip) * f * mu;
401: }
402: 
403: export function tireLateral(alpha, peak = 0.16, mu = 1) {
404:   const a = Math.abs(alpha);
405:   let f;
406:   if (a < peak) f = a / peak;
407:   else f = 1 - 0.22 * Math.min(1, (a - peak) / 0.5);
408:   return -Math.sign(alpha) * f * mu;
409: }
