118: function torqueCurve(rpm, redline, peak) {
119:   const x = clamp(rpm / redline, 0, 1.05);
120:   const table = [
121:     [0.00, 0.40], [0.14, 0.58], [0.30, 0.80], [0.52, 0.97],
122:     [0.68, 1.00], [0.82, 0.94], [0.94, 0.83], [1.02, 0.70],
123:   ];
124:   for (let i = 0; i < table.length - 1; i++) {
125:     if (x <= table[i + 1][0]) {
126:       const t = (x - table[i][0]) / (table[i + 1][0] - table[i][0]);
127:       return peak * lerp(table[i][1], table[i + 1][1], t);
128:     }
129:   }
130:   return peak * 0.7;
