198:       if (ny !== 0) { ny = Math.sign(dy); nx = nz = 0; }
199:       _nrm.x = nx; _nrm.y = ny; _nrm.z = nz;
200:       bestImpact = Math.max(bestImpact, this._pushOut(n, _nrm, pen, c.mu));
201:       n.contact = 1;
202:     }
203:     // cylinders
204:     for (const c of this.cylinders) {
205:       if (n.y > c.y1 || n.y < c.y0 - 0.05) continue;
206:       const dx = n.x - c.x, dz = n.z - c.z;
207:       const d2 = dx * dx + dz * dz;
208:       if (d2 > c.r * c.r) continue;
209:       const d = Math.sqrt(d2) || 1e-6;
210:       _nrm.x = dx / d; _nrm.y = 0; _nrm.z = dz / d;
211:       bestImpact = Math.max(bestImpact, this._pushOut(n, _nrm, c.r - d, c.mu));
212:       n.contact = 1;
213:     }
214:     // spheres
215:     for (const c of this.spheres) {
216:       const dx = n.x - c.x, dy = n.y - c.y, dz = n.z - c.z;
217:       const d2 = dx * dx + dy * dy + dz * dz;
218:       if (d2 > c.r * c.r) continue;
219:       const d = Math.sqrt(d2) || 1e-6;
220:       _nrm.x = dx / d; _nrm.y = dy / d; _nrm.z = dz / d;
221:       bestImpact = Math.max(bestImpact, this._pushOut(n, _nrm, c.r - d, c.mu));
222:       n.contact = 1;
223:     }
224:     // ramps (wedge height field)
225:     for (const c of this.ramps) {
226:       const { u, v } = this.toLocal(c, n.x, n.z);
227:       if (Math.abs(v) > c.w / 2) continue;
228:       const along = u + c.l / 2;
229:       if (along < 0 || along > c.l) continue;
230:       const surf = this.ground.height(n.x, n.z) + c.h * (along / c.l);
231:       if (n.y >= surf) continue;
232:       const pen = (surf - n.y) * 0.98;
233:       this.surfaceNormal(n.x, n.z, _nrm);
234:       bestImpact = Math.max(bestImpact, this._pushOut(n, _nrm, pen, c.mu));
235:       n.contact = 1;
236:     }
237:     return bestImpact;
238:   }
239: 
240:   _pushOut(n, nrm, pen, mu) {
241:     const speedIn = -(n.vx * nrm.x + n.vy * nrm.y + n.vz * nrm.z);
242:     n.x += nrm.x * (pen + 0.0004);
243:     n.y += nrm.y * (pen + 0.0004);
244:     n.z += nrm.z * (pen + 0.0004);
245:     this._tangentDamp(n, nrm, pen, mu);
246:     return speedIn;
247:   }
248: 
249:   _tangentDamp(n, nrm, pen, mu) {
250:     let dx = n.x - n.px, dy = n.y - n.py, dz = n.z - n.pz;
251:     const dn = dx * nrm.x + dy * nrm.y + dz * nrm.z;
252:     dx -= dn * nrm.x; dy -= dn * nrm.y; dz -= dn * nrm.z;
253:     const len = Math.hypot(dx, dy, dz);
254:     if (len < 1e-9) return;
255:     // Coulomb budget: friction can cancel displacement up to mu * penetration
256:     const lim = mu * Math.max(pen, 0.0004) * 2.2;
257:     if (len > lim) {
258:       const k = 1 - lim / len;
259:       n.x -= dx * k; n.y -= dy * k; n.z -= dz * k;
260:     }
261:   }
262: }
263: 
264: const _nrm = { x: 0, y: 1, z: 0 };
