722:     this._accelSmooth.y += (dvy - this._accelSmooth.y) * k;
723:     this._accelSmooth.z += (dvz - this._accelSmooth.z) * k;
724:     const f = this.frame.fwd, r = this.frame.right;
725:     const gl = (this._accelSmooth.x * f.x + this._accelSmooth.z * f.z) / 9.81;
726:     const gLat = (this._accelSmooth.x * r.x + this._accelSmooth.z * r.z) / 9.81;
727:     this.gforce.x += (gLat - this.gforce.x) * Math.min(1, h * 10);
728:     this.gforce.z += (gl - this.gforce.z) * Math.min(1, h * 10);
729:     const gmag = Math.hypot(this.gforce.x, this.gforce.z);
730:     if (gmag > this.gforce.peak) this.gforce.peak = gmag;
731:     this.speedKph = Math.abs(this.forwardSpeedKph());
732: 
733:     // grounding / air time
734:     let contactCount = 0;
735:     for (const w of this.wheels) if (w.contact) contactCount++;
736:     this.grounded = contactCount;
737:     if (contactCount === 0) this.airTime += h; else this.airTime = 0;
738: 
739:     // impact handling
740:     if (this.solver.impactSpeed > 3.2 && this.impactCooldown <= 0) {
741:       this.registerImpact(this.solver.impactSpeed);
742:       this.impactCooldown = 0.22;
743:     }
744:     if (this.impactCooldown > 0) this.impactCooldown -= h;
745: 
746:     // wheel damage on landings
747:     for (const w of this.wheels) {
748:       if (w.contact && w.load > 0) {
749:         const hard = Math.max(0, (w.load / this.spec.mass / 9.81) - 2.3);
750:         if (hard > 0) w.damage = clamp(w.damage + hard * h * 0.05, 0, 1);
751:       }
752:     }
753:   }
754: 
755:   registerImpact(speed) {
756:     const imp = speed;
757:     this.lastImpact = imp;
758:     this.events.push({ type: 'impact', speed: imp, pos: this.body.center() });
759:     if (imp > 4.5) {
760:       const pts = Math.min(2400, Math.pow(imp - 3.0, 2.1) * 1.6);
761:       this.crashScore += pts;
762:       this.gforce.peak = Math.max(this.gforce.peak, imp / 9.81 * 0.9);
763:     }
764:   }
765: 
766:   centerZ() {
767:     // rough longitudinal centre of the body
768:     let z = 0;
769:     for (const n of this.body.nodes) z += n.z;
770:     return z / this.body.nodes.length;
771:   }
